// Verifies X-LendLoop-Signature over the exact bytes Convex sent.
// Signed message: `${timestamp}.POST loan-event.${rawBody}`
const crypto = require('crypto');
const secret = $env.LENDLOOP_HMAC_SECRET;
const item = $input.first();
const headers = item.json.headers || {};
const timestamp = headers['x-lendloop-timestamp'];
const signature = headers['x-lendloop-signature'] || '';

let raw;
try {
  raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
} catch (e) {
  raw = item.binary && item.binary.data ? Buffer.from(item.binary.data.data, 'base64').toString('utf8') : null;
}

const fail = (reason) => [{ json: { valid: false, reason } }];
if (!secret) return fail('n8n is missing LENDLOOP_HMAC_SECRET');
if (!raw || !timestamp || !signature) return fail('missing signature headers or body');
if (!/^\d{10,16}$/.test(timestamp) || Math.abs(Date.now() - Number(timestamp)) > 5 * 60 * 1000) return fail('stale or malformed timestamp');

const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(`${timestamp}.POST loan-event.${raw}`).digest('hex');
const a = Buffer.from(expected);
const b = Buffer.from(signature);
if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) return fail('bad signature');

const event = JSON.parse(raw);

// Convex retries when it does not see a 2xx, so the same event can arrive
// twice. Remember recent event ids (persists across production executions).
const state = $getWorkflowStaticData('global');
state.seen = state.seen || [];
const duplicate = state.seen.includes(event.eventId);
if (!duplicate) {
  state.seen.push(event.eventId);
  if (state.seen.length > 500) state.seen = state.seen.slice(-500);
}

return [{ json: { valid: true, duplicate, event } }];

const { duplicate, event } = $input.first().json;
if (duplicate) return []; // already handled; stop quietly

const { loan, tool, recipient, counterpart } = event;
const dates = `${loan.startDate} to ${loan.endDate}`;
const copy = {
  'loan.requested': [`${counterpart.name} wants to borrow your ${tool.name}`, `${counterpart.name} asked to borrow your ${tool.name} from ${dates}. Open LendLoop to approve or decline.`],
  'loan.approved': [`Approved: ${tool.name}`, `${counterpart.name} approved your request for the ${tool.name} (${dates}). Coordinate pickup with them.`],
  'loan.declined': [`Request declined: ${tool.name}`, `Your request for the ${tool.name} (${dates}) was declined.${loan.reason ? ' Reason: ' + loan.reason : ''}`],
  'loan.cancelled': [`Request cancelled: ${tool.name}`, `${counterpart.name} cancelled their request for your ${tool.name} (${dates}).`],
  'loan.returned': [`Returned: ${tool.name}`, `${counterpart.name} marked the ${tool.name} as returned. Thanks for borrowing responsibly!`],
}[event.event];

if (!copy) throw new Error(`Unknown event type ${event.event}`);

return [{ json: {
  eventId: event.eventId,
  to: recipient.email,
  subject: `[LendLoop] ${copy[0]}`,
  text: `Hi ${recipient.name},\n\n${copy[1]}\n\n— LendLoop`,
} }];

// Reports the outcome back to Convex. Idempotent on eventId, so the
// HTTP retry below is safe.
const crypto = require('crypto');
const composed = $('Compose message').first().json;
const failed = Boolean($json.error);
const body = JSON.stringify({
  eventId: composed.eventId,
  status: failed ? 'failed' : 'sent',
  detail: failed ? String($json.error.message || $json.error).slice(0, 280) : 'Email sent by n8n.',
});
const path = '/n8n/notification-results';
const ts = String(Date.now());
const sig = 'sha256=' + crypto.createHmac('sha256', $env.LENDLOOP_HMAC_SECRET).update(`${ts}.POST ${path}.${body}`).digest('hex');
return { json: { url: $env.CONVEX_SITE_URL + path, ts, sig, body } };
